from pptx import Presentation
from pptx.oxml.ns import qn
import glob
files = sorted(glob.glob('deck-lab/*.pptx'))
banned = [f.split('/')[-1] for f in files if any(k in f.split('/')[-1] for k in ('test','smoke','tmp','probe','draft','_intentional','_bad','_collision','_fp','_real_collision','_true_collision','_tight_design','_t.pptx'))]
print('files:', len(files), '| banned/demo-name files present:', banned or 'none')
bad=[]
for f in files:
    if any(k in f for k in banned): continue
    prs=Presentation(f); W,H=prs.slide_width, prs.slide_height
    iss=[]
    if len(prs.slides._sldIdLst)<6: iss.append('<6')
    for i,sl in enumerate(prs.slides,1):
        w=sum(len(s.text_frame.text.split()) for s in sl.shapes if s.has_text_frame)
        if w>70: iss.append(f's{i}:{w}w')
        if sl._element.find(qn('p:transition')) is None: iss.append(f's{i}:trans')
        for s in sl.shapes:
            x,y,cx,cy=s.left or 0,s.top or 0,s.width or 0,s.height or 0
            if x<0 or y<0 or x+cx>W or y+cy>H: iss.append(f's{i}:oob')
            if s.has_text_frame:
                for p in s.text_frame.paragraphs:
                    for r in p.runs:
                        if r.font.size and r.font.size.pt<12: iss.append(f's{i}:<12')
    if iss: bad.append((f.split('/')[-1],iss))
print('portfolio decks passing all criteria E constraints:', 'ALL' if not bad else bad)
EOF

